package main

import (
	"fmt"
	"strings"
)

var dnsTypeNames = map[int64]string{1: "A", 2: "NS", 5: "CNAME", 6: "SOA", 12: "PTR", 15: "MX", 16: "TXT", 28: "AAAA"}

func typeName(t int64) string {
	if name, ok := dnsTypeNames[t]; ok {
		return name
	}
	return fmt.Sprintf("TYPE%d", t)
}
func rcodeName(code int64) string {
	names := []string{"NoError", "FormErr", "ServFail", "NXDomain", "NotImp", "Refused"}
	if code < int64(len(names)) {
		return names[code]
	}
	return fmt.Sprintf("RCODE%d", code)
}
func className(c int64) string {
	if c == 1 {
		return "IN"
	}
	return fmt.Sprintf("CLASS%d", c)
}
func labelText(bytes []byte) string {
	text := ""
	for _, b := range bytes {
		if b >= 33 && b <= 126 && b != 46 && b != 92 {
			text += string(b)
		} else {
			text += fmt.Sprintf("\\%03d", b)
		}
	}
	return text
}
func ipv6Notation(bytes []byte) string {
	groups := []int64{}
	texts := []string{}
	for i := 0; i < 16; i += 2 {
		group := readInt(bytes, i, 2)
		groups = append(groups, group)
		texts = append(texts, fmt.Sprintf("%x", group))
	}
	bestStart, bestLength := -1, 1
	for i := 0; i < len(groups); {
		if groups[i] != 0 {
			i++
			continue
		}
		end := i
		for end < len(groups) && groups[end] == 0 {
			end++
		}
		if end-i > bestLength {
			bestStart, bestLength = i, end-i
		}
		i = end
	}
	if bestStart < 0 {
		return strings.Join(texts, ":")
	}
	return strings.Join(texts[:bestStart], ":") + "::" + strings.Join(texts[bestStart+bestLength:], ":")
}

type DNSReader struct{ Message []byte }

func (r DNSReader) Chunk(position, size int) []byte {
	if position+size > len(r.Message) {
		fail("dns: truncated")
	}
	return r.Message[position : position+size]
}
func (r DNSReader) Integer(position, size int) int64 {
	return readInt(r.Chunk(position, size), 0, size)
}
func (r DNSReader) Name(position int) (string, int) {
	labels := []string{}
	pointers, after := 0, -1
	for {
		length := int(r.Integer(position, 1))
		if length == 0 {
			if after < 0 {
				after = position + 1
			}
			break
		}
		if length >= 192 {
			low := int(r.Integer(position+1, 1))
			if after < 0 {
				after = position + 2
			}
			pointers++
			if pointers > 16 {
				fail("dns: compression loop")
			}
			target := (length-192)*256 + low
			if target >= len(r.Message) {
				fail("dns: pointer out of range")
			}
			position = target
		} else if length >= 64 {
			fail("dns: bad label type")
		} else {
			labels = append(labels, labelText(r.Chunk(position+1, length)))
			position += length + 1
		}
	}
	notation := strings.Join(labels, ".")
	if len(labels) == 0 {
		notation = "<root>"
	}
	return notation, after
}
func (r DNSReader) Rdata(t int64, start, length int) (string, int) {
	switch t {
	case 1:
		return ipv4Notation(r.Integer(start, 4)), start + 4
	case 28:
		return ipv6Notation(r.Chunk(start, 16)), start + 16
	case 2, 5, 12:
		return r.Name(start)
	case 15:
		preference := r.Integer(start, 2)
		exchange, end := r.Name(start + 2)
		return fmt.Sprintf("%d %s", preference, exchange), end
	case 6:
		primary, pos := r.Name(start)
		mailbox, pos := r.Name(pos)
		parts := []string{primary, mailbox}
		for i := 0; i < 5; i++ {
			parts = append(parts, fmt.Sprint(r.Integer(pos, 4)))
			pos += 4
		}
		return strings.Join(parts, " "), pos
	default:
		return fmt.Sprintf("%d bytes", length), start + length
	}
}
func (r DNSReader) Record(position int, section string, l *Layer) int {
	name, pos := r.Name(position)
	fixed := r.Chunk(pos, 10)
	t, c, ttl, length := readInt(fixed, 0, 2), readInt(fixed, 2, 2), readInt(fixed, 4, 4), int(readInt(fixed, 8, 2))
	start := pos + 10
	r.Chunk(start, length)
	data, end := r.Rdata(t, start, length)
	if end != start+length {
		fail("dns: bad rdata length")
	}
	l.Fields.AddS(section, fmt.Sprintf("%s %s %s %d %s", name, typeName(t), className(c), ttl, data))
	if section == "dns.answer" && t == 1 {
		l.Fields.AddN("dns.a", readInt(r.Message, start, 4))
	}
	return start + length
}
func dissectDNS(message []byte) *Layer {
	r := DNSReader{message}
	header := r.Chunk(0, 12)
	flags := readInt(header, 2, 2)
	counts := []int{}
	for i := 4; i < 12; i += 2 {
		counts = append(counts, int(readInt(header, i, 2)))
	}
	l := newLayer()
	f := l.Fields
	f.N("dns.id", readInt(header, 0, 2))
	f.N("dns.flags", flags)
	f.N("dns.flags.response", flags/32768%2)
	f.N("dns.flags.opcode", flags/2048%16)
	f.N("dns.flags.rcode", flags%16)
	for i, name := range []string{"dns.count.queries", "dns.count.answers", "dns.count.auth_rr", "dns.count.add_rr"} {
		f.N(name, int64(counts[i]))
	}
	pos := 12
	for i := 0; i < counts[0]; i++ {
		name, end := r.Name(pos)
		tail := r.Chunk(end, 4)
		f.AddS("dns.qry.name", name)
		f.AddN("dns.qry.type", readInt(tail, 0, 2))
		pos = end + 4
	}
	for i, section := range []string{"dns.answer", "dns.authority", "dns.additional"} {
		for j := 0; j < counts[i+1]; j++ {
			pos = r.Record(pos, section, l)
		}
	}
	return l
}

package main

import "sort"

var marks = []string{"retransmission", "out_of_order", "lost_segment", "duplicate_ack"}

const sequenceModulus int64 = 1 << 32

type Endpoint struct{ Address, Port int64 }

func endpointLess(a, b Endpoint) bool {
	if a.Address != b.Address {
		return a.Address < b.Address
	}
	return a.Port < b.Port
}
func endpointPair(a, b Endpoint) [2]Endpoint {
	if endpointLess(b, a) {
		return [2]Endpoint{b, a}
	}
	return [2]Endpoint{a, b}
}

type PreviousAck struct {
	Ack, Window   int64
	Number, Count int
}
type Side struct {
	Name                                         string
	ISN, MSS, WScale, Base, Expected, AdvancedAt int64
	Intervals                                    map[[2]int64]bool
	PreviousAck                                  *PreviousAck
	Packets                                      int
	Payload                                      int64
	Marks                                        map[string]int
}

func newSide(name string) *Side {
	return &Side{Name: name, ISN: -1, MSS: -1, WScale: -1, Base: -1, Expected: -1, Intervals: map[[2]int64]bool{}, Marks: map[string]int{}}
}

type StateEntry struct {
	State  string
	Packet int
}
type StreamEvent struct {
	Packet      int
	Side, Mark  string
	Start, Size int64
}
type Stream struct {
	Number                    int
	Client, Server            Endpoint
	State                     string
	History                   []StateEntry
	Start, End                int64
	Packets, Bytes            int
	Syn, SynAck, HandshakeAck int
	Events                    []StreamEvent
	Closer                    *Side
	FinalAck                  int64
	ClientSide, ServerSide    *Side
}

func (s *Stream) ChangeState(state string, packet int) {
	s.State = state
	s.History = append(s.History, StateEntry{state, packet})
}
func (s *Stream) RecordSyn(side *Side, p *Packet) {
	side.ISN = p.Fields.Num("tcp.seq_raw")
	side.MSS, side.WScale = -1, -1
	if p.Fields.Exists("tcp.options.mss") {
		side.MSS = p.Fields.Num("tcp.options.mss")
	}
	if p.Fields.Exists("tcp.options.wscale") {
		side.WScale = p.Fields.Num("tcp.options.wscale")
	}
	if side == s.ClientSide {
		s.Syn = p.Number
	} else {
		s.SynAck = p.Number
	}
}

type StreamTracker struct {
	Streams       []*Stream
	Latest        map[[2]Endpoint]*Stream
	DuplicateAcks map[int][2]int
}

func newTracker() *StreamTracker {
	return &StreamTracker{Latest: map[[2]Endpoint]*Stream{}, DuplicateAcks: map[int][2]int{}}
}
func (t *StreamTracker) Track(p *Packet) {
	f := p.Fields
	source, destination := Endpoint{f.Num("ip.src"), f.Num("tcp.srcport")}, Endpoint{f.Num("ip.dst"), f.Num("tcp.dstport")}
	seq, ack := f.Num("tcp.seq_raw"), f.Num("tcp.ack_raw")
	syn, fin, rst, hasAck := f.Num("tcp.flags.syn") == 1, f.Num("tcp.flags.fin") == 1, f.Num("tcp.flags.rst") == 1, f.Num("tcp.flags.ack") == 1
	key := endpointPair(source, destination)
	stream := t.Latest[key]
	if stream == nil || (stream.State == "CLOSED" || stream.State == "RESET") && syn && !hasAck {
		stream = &Stream{Number: len(t.Streams), Client: source, Server: destination, State: "ESTABLISHED",
			Start: p.Time, End: p.Time, ClientSide: newSide("client"), ServerSide: newSide("server")}
		if syn && hasAck {
			stream.Client, stream.Server = destination, source
			stream.State = "SYN_RECEIVED"
			stream.RecordSyn(stream.ServerSide, p)
		} else if syn {
			stream.State = "SYN_SENT"
			stream.RecordSyn(stream.ClientSide, p)
		}
		stream.History = []StateEntry{{stream.State, p.Number}}
		t.Streams = append(t.Streams, stream)
		t.Latest[key] = stream
	}
	f.N("tcp.stream", int64(stream.Number))
	side, other := stream.ClientSide, stream.ServerSide
	if source != stream.Client {
		side, other = other, side
	}
	if side.Base < 0 {
		side.Base = seq
	}
	if hasAck && other.Base < 0 {
		other.Base = ack
	}
	relative := (seq - side.Base + sequenceModulus) % sequenceModulus
	f.N("tcp.seq", relative)
	if hasAck {
		f.N("tcp.ack", (ack-other.Base+sequenceModulus)%sequenceModulus)
	}
	size := f.Num("tcp.len") + f.Num("tcp.flags.syn") + f.Num("tcp.flags.fin")
	mark := ""
	if size > 0 {
		if side.Expected >= 0 && relative != side.Expected {
			if relative > side.Expected {
				mark = "lost_segment"
			} else if side.Intervals[[2]int64{relative, size}] {
				mark = "retransmission"
			} else if p.Time-side.AdvancedAt < 3000 {
				mark = "out_of_order"
			} else {
				mark = "retransmission"
			}
		}
		side.Intervals[[2]int64{relative, size}] = true
		if side.Expected < 0 || relative+size > side.Expected {
			side.Expected, side.AdvancedAt = relative+size, p.Time
		}
	} else if hasAck && !rst {
		previous := side.PreviousAck
		if previous != nil && ack == previous.Ack && f.Num("tcp.window") == previous.Window {
			mark = "duplicate_ack"
			previous.Count++
			t.DuplicateAcks[p.Number] = [2]int{previous.Number, previous.Count}
		}
	}
	if hasAck && mark != "duplicate_ack" {
		side.PreviousAck = &PreviousAck{Ack: ack, Window: f.Num("tcp.window"), Number: p.Number}
	}
	if mark != "" {
		f.N("tcp.analysis."+mark, 1)
		side.Marks[mark]++
		stream.Events = append(stream.Events, StreamEvent{p.Number, side.Name, mark, relative, size})
	}
	window := f.Num("tcp.window")
	if stream.ClientSide.WScale >= 0 && stream.ServerSide.WScale >= 0 && !syn {
		window *= 1 << uint(side.WScale)
	}
	f.N("tcp.window.calc", window)
	state := stream.State
	if rst {
		if state != "CLOSED" && state != "RESET" {
			stream.ChangeState("RESET", p.Number)
		}
	} else if state == "SYN_SENT" && syn && hasAck && side == stream.ServerSide && ack == (stream.ClientSide.ISN+1)%sequenceModulus {
		stream.ChangeState("SYN_RECEIVED", p.Number)
		stream.RecordSyn(stream.ServerSide, p)
	} else if state == "SYN_RECEIVED" && side == stream.ClientSide && hasAck && !syn && ack == (stream.ServerSide.ISN+1)%sequenceModulus {
		stream.ChangeState("ESTABLISHED", p.Number)
		stream.HandshakeAck = p.Number
	} else if state == "ESTABLISHED" && fin {
		stream.ChangeState("FIN_WAIT", p.Number)
		stream.Closer = side
	} else if state == "FIN_WAIT" && fin && side != stream.Closer {
		stream.ChangeState("CLOSING", p.Number)
		stream.FinalAck = (seq + f.Num("tcp.len") + 1) % sequenceModulus
	} else if state == "CLOSING" && side == stream.Closer && hasAck && ack == stream.FinalAck {
		stream.ChangeState("CLOSED", p.Number)
	}
	side.Packets++
	side.Payload += f.Num("tcp.len")
	stream.Packets++
	stream.Bytes += p.Length
	stream.End = p.Time
}

type Conversation struct {
	Kind                                   int
	A, B                                   Endpoint
	FirstNumber                            int
	FirstTime, LastTime                    int64
	PacketsAB, BytesAB, PacketsBA, BytesBA int
}

func (c *Conversation) Packets() int { return c.PacketsAB + c.PacketsBA }
func (c *Conversation) Bytes() int   { return c.BytesAB + c.BytesBA }

type ConversationKey struct {
	Kind, Stream int
	Pair         [2]Endpoint
}

func buildConversations(packets []*Packet) []*Conversation {
	conversations := []*Conversation{}
	table := map[ConversationKey]*Conversation{}
	for _, p := range packets {
		f := p.Fields
		if !f.Exists("ip.src") {
			continue
		}
		type View struct {
			Key                 ConversationKey
			Source, Destination Endpoint
		}
		source, destination := Endpoint{f.Num("ip.src"), -1}, Endpoint{f.Num("ip.dst"), -1}
		views := []View{{ConversationKey{Kind: 0, Pair: endpointPair(source, destination)}, source, destination}}
		if f.Exists("tcp.stream") {
			src, dst := Endpoint{source.Address, f.Num("tcp.srcport")}, Endpoint{destination.Address, f.Num("tcp.dstport")}
			views = append(views, View{ConversationKey{Kind: 1, Stream: int(f.Num("tcp.stream"))}, src, dst})
		}
		if f.Exists("udp.srcport") {
			src, dst := Endpoint{source.Address, f.Num("udp.srcport")}, Endpoint{destination.Address, f.Num("udp.dstport")}
			views = append(views, View{ConversationKey{Kind: 2, Pair: endpointPair(src, dst)}, src, dst})
		}
		for _, v := range views {
			c := table[v.Key]
			if c == nil {
				c = &Conversation{Kind: v.Key.Kind, A: v.Source, B: v.Destination, FirstNumber: p.Number, FirstTime: p.Time}
				table[v.Key] = c
				conversations = append(conversations, c)
			}
			if v.Source == c.A {
				c.PacketsAB++
				c.BytesAB += p.Length
			} else {
				c.PacketsBA++
				c.BytesBA += p.Length
			}
			c.LastTime = p.Time
		}
	}
	sort.Slice(conversations, func(i, j int) bool {
		a, b := conversations[i], conversations[j]
		if a.Bytes() != b.Bytes() {
			return a.Bytes() > b.Bytes()
		}
		if a.Packets() != b.Packets() {
			return a.Packets() > b.Packets()
		}
		if a.Kind != b.Kind {
			return a.Kind < b.Kind
		}
		return a.FirstNumber < b.FirstNumber
	})
	return conversations
}

type EndpointTotals struct {
	Address                                int64
	TxPackets, TxBytes, RxPackets, RxBytes int
}

func (e *EndpointTotals) Packets() int { return e.TxPackets + e.RxPackets }
func (e *EndpointTotals) Bytes() int   { return e.TxBytes + e.RxBytes }
func buildEndpoints(packets []*Packet) []*EndpointTotals {
	table := map[int64]*EndpointTotals{}
	for _, p := range packets {
		if !p.Fields.Exists("ip.src") {
			continue
		}
		source, destination := p.Fields.Num("ip.src"), p.Fields.Num("ip.dst")
		for _, address := range []int64{source, destination} {
			if table[address] == nil {
				table[address] = &EndpointTotals{Address: address}
			}
		}
		sender, receiver := table[source], table[destination]
		sender.TxPackets++
		sender.TxBytes += p.Length
		receiver.RxPackets++
		receiver.RxBytes += p.Length
	}
	endpoints := []*EndpointTotals{}
	for _, e := range table {
		endpoints = append(endpoints, e)
	}
	sort.Slice(endpoints, func(i, j int) bool {
		a, b := endpoints[i], endpoints[j]
		if a.Bytes() != b.Bytes() {
			return a.Bytes() > b.Bytes()
		}
		if a.Packets() != b.Packets() {
			return a.Packets() > b.Packets()
		}
		return a.Address < b.Address
	})
	return endpoints
}

package main

import (
	"encoding/hex"
	"fmt"
	"os"
	"regexp"
	"strings"
)

type FieldValue struct {
	Number int64
	Text   string
}
type Fields map[string][]FieldValue

func (f Fields) N(name string, value int64)    { f[name] = []FieldValue{{Number: value}} }
func (f Fields) S(name, value string)          { f[name] = []FieldValue{{Text: value}} }
func (f Fields) AddN(name string, value int64) { f[name] = append(f[name], FieldValue{Number: value}) }
func (f Fields) AddS(name, value string)       { f[name] = append(f[name], FieldValue{Text: value}) }
func (f Fields) Num(name string) int64 {
	if len(f[name]) == 0 {
		return 0
	}
	return f[name][0].Number
}
func (f Fields) Text(name string) string {
	if len(f[name]) == 0 {
		return ""
	}
	return f[name][0].Text
}
func (f Fields) Exists(name string) bool { return len(f[name]) > 0 }

type Packet struct {
	Number, Length  int
	Time            int64
	Data, Remaining []byte
	Error           string
	Layers          []string
	Fields          Fields
}

func readLines(path string) []string {
	b, e := os.ReadFile(path)
	if e != nil {
		panic(e)
	}
	if len(b) == 0 {
		return nil
	}
	return strings.Split(strings.TrimSuffix(string(b), "\n"), "\n")
}
func readCapture() []*Packet {
	packets := []*Packet{}
	type DumpLine struct {
		Number int
		Text   string
	}
	dumps := [][]DumpLine{}
	pattern := regexp.MustCompile(`^[0-9a-f]{4}  [0-9a-f]{2}( [0-9a-f]{2}){0,15}$`)
	for i, text := range readLines("input/capture.txt") {
		if strings.HasPrefix(text, "PACKET ") {
			p := &Packet{Fields: Fields{}}
			fmt.Sscanf(text, "PACKET %d %d %d", &p.Number, &p.Time, &p.Length)
			packets = append(packets, p)
			dumps = append(dumps, nil)
		} else if text != "" {
			last := len(dumps) - 1
			dumps[last] = append(dumps[last], DumpLine{i + 1, text})
		}
	}
	for i, p := range packets {
		data := []byte{}
		for _, dump := range dumps[i] {
			text := dump.Text
			if !pattern.MatchString(text) {
				p.Error = fmt.Sprintf("dump: bad line %d", dump.Number)
				break
			}
			var offset int
			fmt.Sscanf(text[:4], "%x", &offset)
			if offset != len(data) {
				p.Error = fmt.Sprintf("dump: offset mismatch at line %d", dump.Number)
				break
			}
			b, _ := hex.DecodeString(strings.ReplaceAll(text[6:], " ", ""))
			data = append(data, b...)
		}
		if p.Error == "" {
			if len(data) != p.Length {
				p.Error = fmt.Sprintf("dump: length mismatch (header %d, data %d)", p.Length, len(data))
			} else {
				p.Data = data
			}
		}
	}
	return packets
}
func hexDumpLines(data []byte) []string {
	lines := []string{}
	for offset := 0; offset < len(data); offset += 16 {
		piece := data[offset:min(offset+16, len(data))]
		bytes := []string{}
		text := ""
		for _, b := range piece {
			bytes = append(bytes, fmt.Sprintf("%02x", b))
			if b >= 32 && b <= 126 {
				text += string(b)
			} else {
				text += "."
			}
		}
		lines = append(lines, fmt.Sprintf("%04x  %-47s  |%s|", offset, strings.Join(bytes, " "), text))
	}
	return lines
}

package main

import (
	"fmt"
	"strings"
)

type Malformed string

func fail(reason string) { panic(Malformed(reason)) }

type Layer struct {
	Fields             Fields
	Next               string
	Payload, Remaining []byte
}

func newLayer() *Layer { return &Layer{Fields: Fields{}} }
func readInt(data []byte, index, size int) int64 {
	value := int64(0)
	for _, b := range data[index : index+size] {
		value = value*256 + int64(b)
	}
	return value
}
func checksumStatus(data []byte) string {
	total := int64(0)
	for i := 0; i < len(data); i += 2 {
		value := int64(data[i]) * 256
		if i+1 < len(data) {
			value += int64(data[i+1])
		}
		total += value
	}
	for total > 65535 {
		total = total%65536 + total/65536
	}
	if total == 65535 {
		return "good"
	}
	return "bad"
}
func macNotation(value int64) string {
	fields := make([]string, 6)
	for i := 5; i >= 0; i-- {
		fields[i] = fmt.Sprintf("%02x", value%256)
		value /= 256
	}
	return strings.Join(fields, ":")
}
func ipv4Notation(value int64) string {
	fields := make([]string, 4)
	for i := 3; i >= 0; i-- {
		fields[i] = fmt.Sprint(value % 256)
		value /= 256
	}
	return strings.Join(fields, ".")
}
func dissectEthernet(data []byte) *Layer {
	if len(data) < 14 {
		fail("eth: truncated")
	}
	l := newLayer()
	t := readInt(data, 12, 2)
	l.Fields.N("eth.dst", readInt(data, 0, 6))
	l.Fields.N("eth.src", readInt(data, 6, 6))
	l.Fields.N("eth.type", t)
	if t == 2054 {
		l.Next = "arp"
	} else if t == 2048 {
		l.Next = "ip"
	}
	if l.Next != "" {
		l.Payload = data[14:]
	} else {
		l.Remaining = data[14:]
	}
	return l
}
func dissectARP(data []byte) *Layer {
	if len(data) < 28 {
		fail("arp: truncated")
	}
	if readInt(data, 0, 2) != 1 || readInt(data, 2, 2) != 2048 || data[4] != 6 || data[5] != 4 {
		fail("arp: unsupported format")
	}
	l := newLayer()
	l.Fields.N("arp.opcode", readInt(data, 6, 2))
	l.Fields.N("arp.src.hw", readInt(data, 8, 6))
	l.Fields.N("arp.src.ip", readInt(data, 14, 4))
	l.Fields.N("arp.dst.hw", readInt(data, 18, 6))
	l.Fields.N("arp.dst.ip", readInt(data, 24, 4))
	return l
}
func dissectIPv4(data []byte) *Layer {
	if len(data) < 20 {
		fail("ip: truncated header")
	}
	version := data[0] / 16
	if version != 4 {
		fail(fmt.Sprintf("ip: bad version %d", version))
	}
	h := int(data[0]%16) * 4
	if h < 20 {
		fail(fmt.Sprintf("ip: bad header length %d", h))
	}
	if len(data) < h {
		fail("ip: truncated header")
	}
	t := int(readInt(data, 2, 2))
	if t < h {
		fail(fmt.Sprintf("ip: bad total length %d", t))
	}
	if t > len(data) {
		fail(fmt.Sprintf("ip: truncated (total length %d, available %d)", t, len(data)))
	}
	flags := readInt(data, 6, 2)
	mf, offset := flags/8192%2, flags%8192*8
	l := newLayer()
	f := l.Fields
	f.N("ip.hdr_len", int64(h))
	f.N("ip.tos", int64(data[1]))
	f.N("ip.len", int64(t))
	f.N("ip.id", readInt(data, 4, 2))
	f.N("ip.flags.df", flags/16384%2)
	f.N("ip.flags.mf", mf)
	f.N("ip.frag_offset", offset)
	f.N("ip.ttl", int64(data[8]))
	f.N("ip.proto", int64(data[9]))
	f.N("ip.checksum", readInt(data, 10, 2))
	f.S("ip.checksum.status", checksumStatus(data[:h]))
	f.N("ip.src", readInt(data, 12, 4))
	f.N("ip.dst", readInt(data, 16, 4))
	payload := data[h:t]
	if mf == 1 || offset != 0 {
		f.N("ip.fragment", 1)
		l.Remaining = payload
	} else {
		switch data[9] {
		case 1:
			l.Next = "icmp"
		case 17:
			l.Next = "udp"
		case 6:
			l.Next = "tcp"
		}
		if l.Next == "" {
			l.Remaining = payload
		} else {
			l.Payload = payload
		}
	}
	return l
}

